CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, email VARCHAR(320) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, is_admin BOOLEAN NOT NULL DEFAULT FALSE, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
CREATE TABLE IF NOT EXISTS api_sessions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, access_hash CHAR(64) NOT NULL UNIQUE, refresh_hash CHAR(64) NOT NULL UNIQUE, access_expires_at DATETIME(6) NOT NULL, refresh_expires_at DATETIME(6) NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
CREATE TABLE IF NOT EXISTS password_reset_tokens (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at DATETIME(6) NOT NULL, created_at DATETIME(6) NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
CREATE TABLE IF NOT EXISTS movies (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, normalized_id VARCHAR(128) NOT NULL UNIQUE, compressed_id VARCHAR(128) NOT NULL, release_date DATE, cover_image_url TEXT, is_hidden BOOLEAN NOT NULL DEFAULT FALSE, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, INDEX movies_release_date_idx (release_date, normalized_id)) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
CREATE TABLE IF NOT EXISTS actresses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, fanza_id BIGINT UNIQUE, name VARCHAR(512) NOT NULL, search_name VARCHAR(512) NOT NULL, image_url TEXT, raw_json LONGTEXT, is_hidden BOOLEAN NOT NULL DEFAULT FALSE, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, INDEX actresses_search_name_idx (search_name(191))) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
CREATE TABLE IF NOT EXISTS source_pages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, source VARCHAR(32) NOT NULL, url TEXT NOT NULL, url_hash CHAR(64) NOT NULL UNIQUE, raw_html LONGTEXT NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
CREATE TABLE IF NOT EXISTS source_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, source VARCHAR(32) NOT NULL, external_id VARCHAR(191) NOT NULL, normalized_id VARCHAR(128) NOT NULL, source_page_id BIGINT UNSIGNED, priority INTEGER NOT NULL DEFAULT 0, title TEXT NOT NULL, release_date DATE, description LONGTEXT, source_url TEXT, cover_image_url TEXT, thumbnail_image_url TEXT, metadata_json LONGTEXT, raw_json LONGTEXT, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, UNIQUE KEY source_external_idx (source, external_id), INDEX source_items_normalized_id_idx (normalized_id), FOREIGN KEY (source_page_id) REFERENCES source_pages(id) ON DELETE SET NULL) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
CREATE TABLE IF NOT EXISTS movie_cast (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, movie_id BIGINT UNSIGNED NOT NULL, fanza_id BIGINT, name VARCHAR(512) NOT NULL, INDEX movie_cast_movie_id_idx (movie_id), INDEX movie_cast_fanza_id_idx (fanza_id), INDEX movie_cast_name_idx (name(191)), FOREIGN KEY (movie_id) REFERENCES movies(id) ON DELETE CASCADE) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
CREATE TABLE IF NOT EXISTS settings (name VARCHAR(100) PRIMARY KEY, value LONGTEXT NOT NULL, updated_at DATETIME(6) NOT NULL) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
CREATE TABLE IF NOT EXISTS search_cooldowns (normalized_id VARCHAR(128) PRIMARY KEY, searched_at DATETIME(6) NOT NULL) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
